#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Tensor-core tiled Conv2d forward kernel (bf16 in/out, fp32 accumulation).
// Each block computes a 16 x 16 output tile for all 32 output channels.
// The convolution is evaluated as W[CO,K] x im2col(X)[K,PIXELS] using
// bf16 WMMA fragments. K is processed in padded 32-element chunks, while
// the input tile is staged once in shared memory to preserve halo reuse.
// OPTIMIZATION (shared-memory bank-conflict reduction): the WMMA A and B
// operands are staged with skewed leading dimensions (SW_LD / SC_LD).
// With a flat 256-element leading dimension the row stride of the B
// operand is 512 bytes, so every WMMA B row lands on the same bank group
// and the load_matrix_sync replays serialize. Adding an 8-element skew
// staggers successive K-rows across banks, removing those conflicts.
// OPTIMIZATION (occupancy lift): request 4 resident blocks per SM via
// __launch_bounds__(256, 4). The profiler shows theoretical occupancy
// capped at 50% by the 79 registers/thread (3 x 256 threads/SM). With
// K = Cin*KH*KW = 27 fitting in a single K-chunk, the kernel is
// issue-limited rather than pipeline-limited, so capping the kernel at
// 64 registers/thread (4 blocks/SM, ~66% occupancy) adds a fourth
// resident block per SM and raises scheduler warp supply without
// changing the tiling, MMA structure, or numerics.
    const T* __restrict__ X,
    const T* __restrict__ W,
__global__ void __launch_bounds__(256, 4) conv2d_tiled_kernel(
    int N, int Cin, int H, int Win,
    int KH, int KW,
    int stride, int pad,
    int Hout, int Wout)
{
  constexpr int Threads = 256;
  constexpr int TILE_H  = 16;
  constexpr int TILE_W  = 16;
  constexpr int PIXELS  = TILE_H * TILE_W;
  constexpr int WARPS   = Threads / 32;
  constexpr int K_STRIDE = 32;
  constexpr int WMMA_M  = 16;
  constexpr int WMMA_N  = 16;
  constexpr int WMMA_K  = 16;
  constexpr int M_TILES = CO / WMMA_M;
  constexpr int N_TILES = PIXELS / WMMA_N;
  constexpr int TILES_PER_WARP = 4;
  // Skewed shared-memory leading dimensions (elements). The +8 keeps the
  // ld a multiple of 8 (required for bf16 WMMA) while staggering rows.
  constexpr int SW_LD = K_STRIDE + 8;
  constexpr int SC_LD = PIXELS + 8;
  static_assert(CO == 32, "This kernel expects 32 output channels");
  static_assert(WARPS * TILES_PER_WARP == M_TILES * N_TILES,
                "Invalid warp-to-WMMA-tile mapping");
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int oh0 = blockIdx.y * TILE_H;
  const int ow0 = blockIdx.x * TILE_W;
  const int K = Cin * KH * KW;
  const int IHt = (TILE_H - 1) * stride + KH;
  const int IWt = (TILE_W - 1) * stride + KW;
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sYn = (int64_t)CO * Hout * Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Int<CO>{}, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<CO>{}, K),
      make_stride((int64_t)K, Int<1>{})
  );
  extern __shared__ __align__(32) __nv_bfloat16 smem_raw[];
  __nv_bfloat16* sW   = smem_raw;
  __nv_bfloat16* sCol = sW + CO * SW_LD;
  // The fp32 accumulator staging buffer aliases the im2col buffer sCol:
  // sCol is fully consumed before the trailing __syncthreads() of the
  // last K-chunk iteration, so reusing its storage removes 8 KB of
  // dynamic shared memory and lifts the smem-imposed occupancy limit.
  float* sC = reinterpret_cast<float*>(sCol);
  __nv_bfloat16* sTile = sCol + K_STRIDE * SC_LD;
  auto sIn = make_tensor(
      make_smem_ptr(sTile),
      make_shape(Cin, IHt, IWt),
      make_stride(IHt * IWt, IWt, Int<1>{})
  );
