    for (int idx = tid; idx < CO * K_STRIDE; idx += Threads) {
      int oc = idx / K_STRIDE;
      int t  = idx - oc * K_STRIDE;
      __nv_bfloat16 v = __float2bfloat16(0.0f);
      if (t < kc) {
        v = __float2bfloat16((float)mW(oc, t_base + t));
      }
      sW[oc * SW_LD + t] = v;
    }
    for (int idx = tid; idx < K_STRIDE * PIXELS; idx += Threads) {
      int p = idx % PIXELS;
      int t = idx / PIXELS;
      __nv_bfloat16 v = __float2bfloat16(0.0f);
      if (t < kc) {
        int tap = t_base + t;
        int kw = tap % KW;
        int r  = tap / KW;
        int kh = r % KH;
        int ic = r / KH;
        int th = p / TILE_W;
        int tw = p - th * TILE_W;
        v = sIn(ic, th * stride + kh, tw * stride + kw);
      }
      sCol[t * SC_LD + p] = v;
    }
    __syncthreads();
    for (int k0 = 0; k0 < kc; k0 += WMMA_K) {
      wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K,
                     __nv_bfloat16, wmma::row_major> a_frag;
      wmma::load_matrix_sync(
          a_frag, sW + m0 * SW_LD + k0, SW_LD);
      #pragma unroll
      for (int j = 0; j < TILES_PER_WARP; ++j) {
        const int n_tile = n_group * TILES_PER_WARP + j;
        const int n0 = n_tile * WMMA_N;
        wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K,
                       __nv_bfloat16, wmma::row_major> b_frag;
        wmma::load_matrix_sync(
            b_frag, sCol + k0 * SC_LD + n0, SC_LD);
        wmma::mma_sync(c_frag[j], a_frag, b_frag, c_frag[j]);
      }
    }
    __syncthreads();
  }
  // Store each 16-channel x 16-pixel accumulator tile through a small
  // per-warp fp32 buffer, converting to bf16 on the coalesced global store.
  float* warp_c = sC + warp * WMMA_M * WMMA_N;
  #pragma unroll
  for (int j = 0; j < TILES_PER_WARP; ++j) {
    const int n_tile = n_group * TILES_PER_WARP + j;
    wmma::store_matrix_sync(
        warp_c, c_frag[j], WMMA_N, wmma::mem_row_major);
    __syncwarp();
    const int oh = oh0 + n_tile;
    for (int e = lane; e < WMMA_M * WMMA_N; e += 32) {
      const int oc = m0 + e / WMMA_N;
      const int tw = e % WMMA_N;
      const int ow = ow0 + tw;
      if (oh < Hout && ow < Wout) {
        mY(oc, oh, ow) = static_cast<T>(warp_c[e]);
      }
    }
    __syncwarp();
  }
}
