// changing the tiling, MMA structure, or numerics.
template <typename T, int CO>
__global__ void __launch_bounds__(256, 4) conv2d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int KH, int KW,
    int stride, int pad,
    int Hout, int Wout)
{
  constexpr int Threads = 256;
  constexpr int TILE_H  = 16;
  constexpr int TILE_W  = 16;
  constexpr int PIXELS  = TILE_H * TILE_W;
  constexpr int WARPS   = Threads / 32;
  constexpr int K_STRIDE = 32;
  constexpr int WMMA_M  = 16;
  constexpr int WMMA_N  = 16;
  constexpr int WMMA_K  = 16;
  constexpr int M_TILES = CO / WMMA_M;
  constexpr int N_TILES = PIXELS / WMMA_N;
  constexpr int TILES_PER_WARP = 4;
  // Skewed shared-memory leading dimensions (elements). The +8 keeps the
  // ld a multiple of 8 (required for bf16 WMMA) while staggering rows.
  constexpr int SW_LD = K_STRIDE + 8;
  constexpr int SC_LD = PIXELS + 8;
  static_assert(CO == 32, "This kernel expects 32 output channels");
  static_assert(WARPS * TILES_PER_WARP == M_TILES * N_TILES,
                "Invalid warp-to-WMMA-tile mapping");
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int oh0 = blockIdx.y * TILE_H;
  const int ow0 = blockIdx.x * TILE_W;
  const int K = Cin * KH * KW;
  const int IHt = (TILE_H - 1) * stride + KH;
  const int IWt = (TILE_W - 1) * stride + KW;
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sYn = (int64_t)CO * Hout * Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Int<CO>{}, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<CO>{}, K),
      make_stride((int64_t)K, Int<1>{})
  );
  extern __shared__ __align__(32) __nv_bfloat16 smem_raw[];
  __nv_bfloat16* sW   = smem_raw;
  __nv_bfloat16* sCol = sW + CO * SW_LD;
  // The fp32 accumulator staging buffer aliases the im2col buffer sCol:
  // sCol is fully consumed before the trailing __syncthreads() of the
  // last K-chunk iteration, so reusing its storage removes 8 KB of
  // dynamic shared memory and lifts the smem-imposed occupancy limit.
  float* sC = reinterpret_cast<float*>(sCol);
  __nv_bfloat16* sTile = sCol + K_STRIDE * SC_LD;
  auto sIn = make_tensor(
      make_smem_ptr(sTile),
      make_shape(Cin, IHt, IWt),
      make_stride(IHt * IWt, IWt, Int<1>{})
  );
  const int ih_base = oh0 * stride - pad;
  const int iw_base = ow0 * stride - pad;
  // Stage the input tile, including the halo, once per block.
  const int tile_elems = Cin * IHt * IWt;
  for (int idx = tid; idx < tile_elems; idx += Threads) {
    int iw = idx % IWt;
    int r  = idx / IWt;
    int ih = r % IHt;
    int ic = r / IHt;
    int gih = ih_base + ih;
    int giw = iw_base + iw;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if ((unsigned)gih < (unsigned)H && (unsigned)giw < (unsigned)Win) {
      v = __float2bfloat16((float)mX(ic, gih, giw));
    }
    sIn(ic, ih, iw) = v;
  }
  __syncthreads();
  using namespace nvcuda;
  const int warp = tid >> 5;
  const int lane = tid & 31;
  const int m_tile = warp % M_TILES;
  const int n_group = warp / M_TILES;
  const int m0 = m_tile * WMMA_M;
  wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float>
      c_frag[TILES_PER_WARP];
  #pragma unroll
  for (int i = 0; i < TILES_PER_WARP; ++i) {
    wmma::fill_fragment(c_frag[i], 0.0f);
  }
  // Evaluate the implicit GEMM in 32-tap chunks. Each chunk is padded
  // with zero weights and zero im2col rows so tail K values are exact.
  for (int t_base = 0; t_base < K; t_base += K_STRIDE) {
    const int kc =
        (K - t_base < K_STRIDE) ? (K - t_base) : K_STRIDE;
    for (int idx = tid; idx < CO * K_STRIDE; idx += Threads) {
      int oc = idx / K_STRIDE;
      int t  = idx - oc * K_STRIDE;
      __nv_bfloat16 v = __float2bfloat16(0.0f);
      if (t < kc) {
        v = __float2bfloat16((float)mW(oc, t_base + t));
      }
      sW[oc * SW_LD + t] = v;
    }
    for (int idx = tid; idx < K_STRIDE * PIXELS; idx += Threads) {
      int p = idx % PIXELS;
      int t = idx / PIXELS;
      __nv_bfloat16 v = __float2bfloat16(0.0f);
      if (t < kc) {
        int tap = t_base + t;
        int kw = tap % KW;
        int r  = tap / KW;
        int kh = r % KH;
        int ic = r / KH;
        int th = p / TILE_W;
        int tw = p - th * TILE_W;
        v = sIn(ic, th * stride + kh, tw * stride + kw);
      }
      sCol[t * SC_LD + p] = v;
    }
    __syncthreads();
    for (int k0 = 0; k0 < kc; k0 += WMMA_K) {
      wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K,
                     __nv_bfloat16, wmma::row_major> a_frag;
      wmma::load_matrix_sync(
          a_frag, sW + m0 * SW_LD + k0, SW_LD);
      #pragma unroll
      for (int j = 0; j < TILES_PER_WARP; ++j) {
        const int n_tile = n_group * TILES_PER_WARP + j;
        const int n0 = n_tile * WMMA_N;
        wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K,
                       __nv_bfloat16, wmma::row_major> b_frag;
        wmma::load_matrix_sync(
            b_frag, sCol + k0 * SC_LD + n0, SC_LD);
        wmma::mma_sync(c_frag[j], a_frag, b_frag, c_frag[j]);
      }
    }
    __syncthreads();
  }
  // Store each 16-channel x 16-pixel accumulator tile through a small
  // per-warp fp32 buffer, converting to bf16 on the coalesced global store.
  float* warp_c = sC + warp * WMMA_M * WMMA_N;
  #pragma unroll
  for (int j = 0; j < TILES_PER_WARP; ++j) {
    const int n_tile = n_group * TILES_PER_WARP + j;
    wmma::store_matrix_sync(
        warp_c, c_frag[j], WMMA_N, wmma::mem_row_major);
    __syncwarp();
    const int oh = oh0 + n_tile;
    for (int e = lane; e < WMMA_M * WMMA_N; e += 32) {
      const int oc = m0 + e / WMMA_N;
      const int tw = e % WMMA_N;
      const int ow = ow0 + tw;
      if (oh < Hout && ow < Wout) {
        mY(oc, oh, ow) = static_cast<T>(warp_c[e]);
      }
    }
    __syncwarp();
  }
}
torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor w, int stride, int padding) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, KH, KW]");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
  TORCH_CHECK(w.scalar_type() == at::kBFloat16, "w must be bfloat16");
  TORCH_CHECK(stride > 0 && padding >= 0, "invalid stride/padding");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  const int64_t N    = x_c.size(0);
  const int64_t Cin  = x_c.size(1);
  const int64_t H    = x_c.size(2);
  const int64_t Win  = x_c.size(3);
  const int64_t Cout = w_c.size(0);
  const int64_t KH   = w_c.size(2);
  const int64_t KW   = w_c.size(3);
  TORCH_CHECK(w_c.size(1) == Cin, "w.size(1) must equal x channels");
  TORCH_CHECK(Cout == 32, "this kernel is specialized for Cout == 32");
  const int64_t Hout = (H + 2 * padding - KH) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - KW) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");
  auto y = torch::empty({N, Cout, Hout, Wout}, x_c.options());
  constexpr int Threads = 256;
  constexpr int TILE_H  = 16;
  constexpr int TILE_W  = 16;
  constexpr int Warps   = 8;
  constexpr int K_STRIDE = 32;
  // Skewed shared-memory leading dimensions, matching the kernel.
  constexpr int SW_LD = K_STRIDE + 8;
  constexpr int SC_LD = TILE_H * TILE_W + 8;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((Wout + TILE_W - 1) / TILE_W),
      (unsigned)((Hout + TILE_H - 1) / TILE_H),
      (unsigned)N
  );
  const int IHt = (TILE_H - 1) * stride + (int)KH;
  const int IWt = (TILE_W - 1) * stride + (int)KW;
  // The per-warp fp32 accumulator buffer aliases the im2col shared
  // buffer inside the kernel, so it no longer adds to dynamic smem.
  const int fixed_smem =
      (int)((32 * SW_LD + K_STRIDE * SC_LD) *
                sizeof(__nv_bfloat16));
  const int smem =
      fixed_smem + (int)(Cin * IHt * IWt * sizeof(__nv_bfloat16));
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_tiled_kernel<cute::bfloat16_t, 32><<<grid, block, smem, stream>>>(
      reinterpret_cast<const cute::bfloat16_t*>(x_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<const cute::bfloat16_t*>(w_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<cute::bfloat16_t*>(y.data_ptr<at::BFloat16>()),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)KH, (int)KW,
      stride, padding,
      (int)Hout, (int)Wout
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
